 "content": "from collections import Counter

def transform(grid):
    """Stamp every all-zero occurrence of the marked motif, preserving the source."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg and v != 0}
    if len(colors) != 1:
        raise ValueError(f"Expected one marker color, got {colors}")
    color = next(iter(colors))
    shape = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    minr, maxr = min(r for r, c in shape), max(r for r, c in shape)
    minc, maxc = min(c for r, c in shape), max(c for r, c in shape)
    shape = [(r-minr, c-minc) for r, c in shape]
    out = [row[:] for row in grid]
    for dr in range(h - (maxr-minr+1) + 1):
        for dc in range(w - (maxc-minc+1) + 1):
            if all(grid[dr+r][dc+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr+r][dc+c] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
