def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    color = min((v for v in counts if v != 0), key=counts.get)
    source = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]

    # Use the longest straight diagonal run as the repeated motif when the
    # marked pattern contains a diagonal spine plus a stray/anchor mark.
    best = []
    for dr, dc in ((1, 1), (1, -1)):
        for r, c in source:
            run = []
            rr, cc = r, c
            while (rr, cc) in set(source):
                run.append((rr, cc))
                rr += dr
                cc += dc
            if len(run) > len(best):
                best = run
    minr = min(r for r, c in best)
    minc = min(c for r, c in best)
    shape = [(r-minr, c-minc) for r, c in best]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r0 in range(h-sh+1):
        for c0 in range(w-sw+1):
            if all(grid[r0+r][c0+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[r0+r][c0+c] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
